  ('e0000000-0000-4000-8000-000000000061', 61, 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'Chemistry', 'MCQ', 4, 1, 'Which of the following sets includes all the species that will change the orange colour of $\text{K}_2\text{Cr}_2\text{O}_7$ in acidic medium?', '[{"key":"A","text":"$\\text{Fe}^{2+}, \\text{Sn}^{2+}, \\text{I}^-, \\text{S}^{2-}$"},{"key":"B","text":"$\\text{S}^{2-}, \\text{Fe}^{3+}, \\text{I}^-, \\text{C}_2\\text{O}_4^{2-}$"},{"key":"C","text":"$\\text{Fe}^{2+}, \\text{NO}_2^-, \\text{SO}_2, \\text{Sn}^{4+}$"},{"key":"D","text":"$\\text{Fe}^{3+}, \\text{SO}_4^{2-}, \\text{S}^{2-}, \\text{Sn}^{4+}$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, 'Standard solution by method of deduction for Chemistry.', 'EASY', 'Chemistry Comprehensive Core', NULL),
  ('e0000000-0000-4000-8000-000000000062', 62, 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'Chemistry', 'MCQ', 4, 1, 'Match List - I with List - II.

